package com.bakery.registry;

import com.bakery.Bakery;
import net.minecraft.registry.Registries;
import net.minecraft.registry.Registry;
import net.minecraft.sound.SoundEvent;

/** The café music tracks the Café Jukebox plays (original, generated by blockbench/gen_music.py). */
public final class BakerySounds {
	public static final String[] TRACKS = {"morning_pastries", "sugar_and_sprinkles", "rainy_window_latte", "kitten_lullaby"};
	public static final SoundEvent[] MUSIC = new SoundEvent[TRACKS.length];

	static {
		for (int i = 0; i < TRACKS.length; i++) {
			MUSIC[i] = com.bakery.platform.Platform.get().register(Registries.SOUND_EVENT, Bakery.id("music." + TRACKS[i]), SoundEvent.of(Bakery.id("music." + TRACKS[i])));
		}
	}

	private BakerySounds() {
	}

	public static void init() {
	}
}
